import { useQuery } from '@tanstack/react-query';

interface BuildSearchResponse {
    data: {
        channels: string[];
        build: {
            buildId: string;
            displayName: string;
            uploadTime: string;
        };
    }[];
    errors: any[];
}

export const BUILD_SEARCH_QUERY_KEY = 'builds';

export const useBuildSearch = (gameId?: string, displayName?: string) => {
    const query = useQuery<BuildSearchResponse>({
        queryKey: [BUILD_SEARCH_QUERY_KEY, gameId, displayName],
        gcTime: 0,
        enabled: Boolean(gameId),
        queryFn: async () => {
            const response = await fetch(`/api/games/${gameId}/builds/search?displayName=${displayName}`);
            return await response.json();
        },
    });

    return query;
};
